create temporary view exp_filter_${grass_region_without_quote} as
select
    exp_group_id
from
    srdi_mart.dim_sr_data_warehouse_abtest_group
where
    local_date = ${local_date}
    and is_rcmd_whitelist = 1
;

--sql_divide_splitter--
create temporary view log_data_${grass_region_without_quote} as
select
    exp_group_ids
    ,coalesce(platform, 'NULL') as platform
    ,cast(coalesce(is_ads, false) as string) as is_ads
    ,concat_ws(
        ','
        ,if(reporting_module = 'Global Search' and reporting_business_line = 'Search', concat('dpm module ', reporting_module, ' business line ', reporting_business_line), null)
        ,algo_tag) AS scenario_tags_str
    ,target_type
    ,row_number() over(partition by request_id, user_id, item_id, location, banner_location order by exp_group_ids desc) as rn
    -- 0.08% cases have multiple exp_group_ids, feature_detail -> choose the one with longer exp_group_ids
from
    srdi_mart.dwd_sr_data_warehouse_platform
where
    grass_region = ${grass_region}
    and local_date = ${local_date}
    and operation = 'impression' -- traffic impression doesn't have source1 & source2 information
    and request_id is not null
    and (
        (reporting_module = 'Global Search' and reporting_business_line = 'Search')
        or size(
            array_intersect(
                split(algo_tag, ','),
                array(
                    'DA_Daily Discover', 'DA_You May Also Like', 'DA_YMAL_Cart', 'DA_RCMD Unify', 'DA_Cart_Unify',
                    'DA_Cart Recommendation', 'DA_mpp_ymal-order_list', 'DA_Shop YMAL', 'DA_Order Successful Recommendation',
                    'DA_odp_ymal-order_detail', 'DA_Me YMAL', 'DA_Buy Again (Me Page)',
                    'DA_DD_PP Unify', 'DA_Search_RCMD'
                )
            )
        ) > 0
    )
;

--sql_divide_splitter--
create temporary view concat_data_${grass_region_without_quote} as
select
     *
    ,filter(
        coalesce(split(if(scenario_tags_str = '', null, scenario_tags_str), ','), array()),
        value -> value in (
            'dpm module Global Search business line Search',
            'DA_Daily Discover', 'DA_You May Also Like', 'DA_YMAL_Cart', 'DA_RCMD Unify', 'DA_Cart_Unify',
            'DA_Cart Recommendation','DA_mpp_ymal-order_list','DA_Shop YMAL', 'DA_Order Successful Recommendation',
            'DA_odp_ymal-order_detail', 'DA_Me YMAL', 'DA_Buy Again (Me Page)',
            'DA_DD_PP Unify', 'DA_Search_RCMD'
        )
    ) as scenario_tags
from log_data_${grass_region_without_quote}
where rn = 1
;

--sql_divide_splitter--
create temporary view explode_table_${grass_region_without_quote} as
select
    exp_group_id
    ,platform
    ,is_ads
    ,scenario_tags
    ,target_type
    ,1 as dedup_imp_cnt
from concat_data_${grass_region_without_quote}
lateral view explode(exp_group_ids) as exp_group_id
;

--sql_divide_splitter--
create temporary view base_table_${grass_region_without_quote} as
select
    filter_data.exp_group_id
    ,platform
    ,is_ads
    ,scenario_tags
    ,target_type
    ,sum(dedup_imp_cnt) as dedup_imp_cnt
from
    explode_table_${grass_region_without_quote} as filter_data
    inner join exp_filter_${grass_region_without_quote} as exp_filter
    on filter_data.exp_group_id = exp_filter.exp_group_id
group by 1,2,3,4,5

;

--sql_divide_splitter--
create temporary view cube_table_${grass_region_without_quote} as
select
    exp_group_id
    ,if(platform is null, '__ALL__', platform) as platform
    ,if(is_ads is null, '__ALL__', is_ads) as is_ads
    ,scenario_tag
    ,if(target_type is null, '__ALL__', target_type) as target_type
    ,sum(dedup_imp_cnt) as dedup_imp_cnt
from base_table_${grass_region_without_quote}
lateral view explode(scenario_tags) AS scenario_tag
group by exp_group_id, scenario_tag, cube(target_type, platform, is_ads)
;

--sql_divide_splitter--
INSERT OVERWRITE TABLE srdi_mart.dws_sr_data_warehouse_platform_exp_level_dedup_1d
PARTITION (exp_type = 'traffic', grass_region = ${grass_region}, local_date = ${local_date})
select
    exp_group_id
    ,is_ads
    ,platform
    ,scenario_tag
    ,target_type
    ,dedup_imp_cnt
from cube_table_${grass_region_without_quote}
